package io.zem.ibox;
import android.content.Context;import android.graphics.Bitmap;import android.media.*;import android.net.Uri;import android.content.res.AssetFileDescriptor;import java.io.*;import java.nio.ByteBuffer;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Produces separate local copies; original media is never opened for writing. */
final class MediaExports {
    static final ExecutorService WORK=Executors.newSingleThreadExecutor();static final AtomicInteger active=new AtomicInteger();
    static String stamp(){return new java.text.SimpleDateFormat("yyyyMMdd-HHmmss",Locale.ROOT).format(new Date());}
    static Uri frame(Context c,Bitmap image,AtomicBoolean cancel)throws Exception{File file=File.createTempFile("frame-",".jpg",c.getCacheDir());try{try(OutputStream out=new FileOutputStream(file)){if(!image.compress(Bitmap.CompressFormat.JPEG,95,out))throw new IOException("Не удалось сохранить кадр");}if(cancel.get())throw new InterruptedIOException("Сохранение отменено");String name="Frame-"+stamp()+".jpg";Uri saved=Library.publish(c,file,name,"image/jpeg","Frames",cancel::get);Library.add(c,saved,name,"image/jpeg",file.length(),"player frame");return saved;}finally{image.recycle();file.delete();}}
    static Uri clip(Context c,Uri source,long startMs,long endMs,AtomicBoolean cancel,java.util.function.IntConsumer progress)throws Exception{
        if(!"content".equals(source.getScheme())||startMs<0||endMs<=startMs)throw new IOException("Неверный промежуток фрагмента");if(android.os.Build.VERSION.SDK_INT==24)return legacyClip(c,source,startMs,endMs,cancel,progress);File file=File.createTempFile("clip-",".mp4",c.getCacheDir());MediaExtractor extractor=new MediaExtractor();MediaMuxer muxer=null;boolean started=false;
        try{try(AssetFileDescriptor fd=c.getContentResolver().openAssetFileDescriptor(source,"r")){if(fd==null)throw new IOException("Нет доступа к оригиналу");if(fd.getLength()<0)extractor.setDataSource(fd.getFileDescriptor());else extractor.setDataSource(fd.getFileDescriptor(),fd.getStartOffset(),fd.getLength());}
            int video=-1;Map<Integer,Integer> tracks=new HashMap<>();muxer=new MediaMuxer(file.getPath(),MediaMuxer.OutputFormat.MUXER_OUTPUT_MPEG_4);
            for(int i=0;i<extractor.getTrackCount();i++){MediaFormat format=extractor.getTrackFormat(i);String mime=format.getString(MediaFormat.KEY_MIME);if(mime==null)continue;if(mime.startsWith("video/")){if(!mime.equals("video/avc")&&!mime.equals("video/hevc")&&!mime.equals("video/mp4v-es"))throw new IOException("Этот формат видео пока нельзя сохранить фрагментом. Можно отправить оригинал");video=i;if(format.containsKey("rotation-degrees"))muxer.setOrientationHint(format.getInteger("rotation-degrees"));}else if(mime.startsWith("audio/")){if(!mime.equals("audio/mp4a-latm")&&!mime.equals("audio/3gpp")&&!mime.equals("audio/amr-wb"))throw new IOException("Формат звука не подходит для фрагмента MP4. Можно отправить оригинал");}else continue;tracks.put(i,muxer.addTrack(format));}
            if(video<0)throw new IOException("В файле нет видеодорожки");extractor.selectTrack(video);extractor.seekTo(startMs*1000,MediaExtractor.SEEK_TO_PREVIOUS_SYNC);long base=extractor.getSampleTime();if(base<0)throw new IOException("Не найдено начало фрагмента");extractor.unselectTrack(video);for(int track:tracks.keySet())extractor.selectTrack(track);extractor.seekTo(base,MediaExtractor.SEEK_TO_PREVIOUS_SYNC);muxer.start();started=true;ByteBuffer bytes=ByteBuffer.allocateDirect(16*1024*1024);MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();int frames=0,lastProgress=-1;
            while(true){if(cancel.get())throw new InterruptedIOException("Сохранение отменено");int track=extractor.getSampleTrackIndex();long time=extractor.getSampleTime();if(track<0||time<0||time>=endMs*1000)break;if(time<base){extractor.advance();continue;}if((extractor.getSampleFlags()&MediaExtractor.SAMPLE_FLAG_ENCRYPTED)!=0)throw new IOException("Защищённое видео нельзя экспортировать");bytes.clear();int n=extractor.readSampleData(bytes,0);if(n<0)break;info.set(0,n,time-base,(extractor.getSampleFlags()&MediaExtractor.SAMPLE_FLAG_SYNC)!=0?MediaCodec.BUFFER_FLAG_KEY_FRAME:0);muxer.writeSampleData(tracks.get(track),bytes,info);if(track==video)frames++;int value=(int)Math.min(100,Math.max(0,(time-base)*100/Math.max(1,endMs*1000-base)));if(value!=lastProgress){progress.accept(value);lastProgress=value;}extractor.advance();}
            if(frames==0)throw new IOException("В выбранном промежутке нет кадров");muxer.stop();started=false;muxer.release();muxer=null;String name="Clip-"+stamp()+".mp4";Uri saved=Library.publish(c,file,name,"video/mp4","Clips",cancel::get);Library.add(c,saved,name,"video/mp4",file.length(),"clip");return saved;
        }finally{extractor.release();if(muxer!=null){try{if(started)muxer.stop();}catch(Exception ignored){}try{muxer.release();}catch(Exception ignored){}}file.delete();}
    }
    private static Uri legacyClip(Context c,Uri source,long startMs,long endMs,AtomicBoolean cancel,java.util.function.IntConsumer progress)throws Exception{
        File file=File.createTempFile("clip-legacy-",".mp4",c.getCacheDir());org.videolan.libvlc.LibVLC engine=null;org.videolan.libvlc.MediaPlayer player=null;
        try{try(AssetFileDescriptor fd=c.getContentResolver().openAssetFileDescriptor(source,"r")){if(fd==null)throw new IOException("Нет доступа к оригиналу");engine=new org.videolan.libvlc.LibVLC(c.getApplicationContext(),new ArrayList<>(Arrays.asList("--no-video-title-show","--sout-mux-caching=0")));player=new org.videolan.libvlc.MediaPlayer(engine);org.videolan.libvlc.Media media=fd.getStartOffset()==0?new org.videolan.libvlc.Media(engine,fd.getFileDescriptor()):new org.videolan.libvlc.Media(engine,fd);
            media.addOption(":sout=#std{access=file,mux=mp4,dst="+file.getPath()+"}");media.addOption(":sout-all");media.addOption(":start-time="+(startMs/1000.0));media.addOption(":stop-time="+(endMs/1000.0));java.util.concurrent.CountDownLatch end=new java.util.concurrent.CountDownLatch(1);AtomicBoolean failed=new AtomicBoolean();player.setEventListener(event->{if(event.type==org.videolan.libvlc.MediaPlayer.Event.EncounteredError){failed.set(true);end.countDown();}else if(event.type==org.videolan.libvlc.MediaPlayer.Event.EndReached)end.countDown();});player.setMedia(media);media.release();player.play();long deadline=android.os.SystemClock.elapsedRealtime()+Math.max(30000,Math.min(600000,(endMs-startMs)*2+15000));while(!end.await(150,TimeUnit.MILLISECONDS)){if(cancel.get())throw new InterruptedIOException("Сохранение отменено");if(android.os.SystemClock.elapsedRealtime()>deadline)throw new IOException("Не удалось завершить фрагмент за отведённое время");long at=player.getTime();progress.accept((int)Math.min(99,Math.max(0,(at-startMs)*100/Math.max(1,endMs-startMs))));}player.stop();if(cancel.get())throw new InterruptedIOException("Сохранение отменено");if(failed.get()||file.length()==0)throw new IOException("Не удалось сохранить этот формат фрагментом. Можно отправить оригинал");}
            player.setEventListener(null);player.release();player=null;engine.release();engine=null;String name="Clip-"+stamp()+".mp4";Uri saved=Library.publish(c,file,name,"video/mp4","Clips",cancel::get);Library.add(c,saved,name,"video/mp4",file.length(),"clip");return saved;
        }finally{if(player!=null){try{player.setEventListener(null);player.stop();}catch(Exception ignored){}player.release();}if(engine!=null)engine.release();file.delete();}
    }

}
